/* ==========================================================================
   >>> EDIT THESE FOUR VALUES, THEN NEVER AGAIN <<<
   ========================================================================== */
const CALENDAR_ID = 'primary';                       // used only if the Doctors tab is empty
const SHEET_ID    = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';    // from the sheet URL
const PUBLIC_BASE = 'https://condone-making-amount.ngrok-free.dev';
const CLINIC_NAME = 'Smile Dental Clinic';
/* ========================================================================== */

/*  GET /webhook/slots?date=2026-10-02&service=cleaning&doctor=dr-ayesha
      doctor: a doctor_id from the Doctors tab, or "any" (the default)
    GET /webhook/slots?list=doctors[&service=cleaning]
      the dentists, optionally only those who do one treatment
    GET /webhook/slots?next=1&service=cleaning[&doctor=dr-ayesha][&lang=ar]
      the next free times over the coming week, a few from each day, so a
      patient on WhatsApp can pick a day and a time in one tap              */
const q        = $input.first().json.query || {};
const listOnly = String(q.list || '').toLowerCase() === 'doctors';
const next     = !listOnly && ['1', 'true', 'yes'].includes(String(q.next || '').toLowerCase());
const NEXT_DAYS = 7;                                  // today and the 7 days after it
const date     = next ? '' : String(q.date || '');
const lg       = String(q.lang || '').trim().toLowerCase();
const lang     = /^ar/.test(lg) ? 'ar' : /roman|latn/.test(lg) ? 'en' : /^ur/.test(lg) ? 'ur' : 'en';
const service  = String(q.service || '').trim();
const doctor   = String(q.doctor || 'any').trim().toLowerCase() || 'any';
if (!listOnly) {
  if (!next && !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Bad or missing "date" (expect YYYY-MM-DD)');
  if (!service) throw new Error('Missing "service"');
}
const base = listOnly || next ? new Date() : new Date(date + 'T00:00:00Z');
const iso  = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
return [{ json: { CALENDAR_ID, SHEET_ID, PUBLIC_BASE, CLINIC_NAME, date, service, doctor, listOnly,
  next, lang, NEXT_DAYS,
  timeMin: iso(new Date(base.getTime() - 86400000)),
  timeMax: iso(new Date(base.getTime() + (next ? NEXT_DAYS + 2 : 2) * 86400000)) } }];

// ===== DentalFlow availability rules =========================================
// The SAME code sits in workflow 01 (which times to offer) and workflow 02
// (re-check at the moment of booking), so the two can never disagree.
//
// Doctors tab:  doctor_id | name | calendar_id | services | email | active
//   services:   comma-separated service ids, or blank / "all"
// Hours tab:    day | open | close | break_start | break_end | closed | doctor
//   A doctor with ANY rows of their own uses only those rows: a day with no
//   row is a day off. A doctor with no rows uses the clinic rows (doctor blank).
// Nobody active in the Doctors tab: one doctor on the clinic calendar, exactly
// as before multi-doctor support. (The tab itself must exist: run the sheet
// upgrade before importing these workflows.)
const DF = (() => {
  const clean = v => String(v ?? '').trim();
  // "14:00", "14:00:00", "14.00" and "2:00 PM" all mean the same time; a sheet may show any of them.
  const toMin = t => {
    const m = /^(\d{1,2})[:.](\d{2})(?::\d{2})?\s*([ap])?\.?m?\.?$/i.exec(clean(t));
    if (!m) return NaN;
    let h = Number(m[1]); const ap = (m[3] || '').toLowerCase();
    if (ap === 'p' && h < 12) h += 12;
    if (ap === 'a' && h === 12) h = 0;
    return h * 60 + Number(m[2]);
  };
  const toHHMM = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  const truthy = v => clean(v).toUpperCase() === 'TRUE';
  const parts = (isoStr, tz) => {
    const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit',
      day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
    const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
    return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
  };
  const dayName = (date, tz) => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long' })
    .format(new Date(date + 'T12:00:00Z')).toLowerCase();

  function settings(rows) { const s = {}; for (const r of rows || []) s[clean(r[0])] = r[1]; return s; }

  function services(rows) {
    return (rows || []).map(r => ({ id: clean(r[0]), name: clean(r[1]), min: Number(r[2]), price: Number(r[3]),
      active: r[4] === undefined || clean(r[4]).toUpperCase() !== 'FALSE' })).filter(s => s.id);
  }

  function doctors(rows, fallbackCalendar, fallbackName) {
    const list = (rows || []).map(r => ({
      id: clean(r[0]).toLowerCase(), name: clean(r[1]) || clean(r[0]), calendarId: clean(r[2]),
      services: clean(r[3]), email: clean(r[4]),
      active: r[5] === undefined || clean(r[5]).toUpperCase() !== 'FALSE'
    })).filter(d => d.id && d.calendarId && d.active);
    if (list.length) return list;
    return [{ id: 'clinic', name: fallbackName || 'the dentist', calendarId: fallbackCalendar || 'primary',
              services: 'all', email: '', active: true, implicit: true }];
  }

  const doesService = (d, svcId) => {
    const s = d.services.toLowerCase();
    return !s || s === 'all' || s.split(/[\s,;]+/).filter(Boolean).includes(String(svcId).toLowerCase());
  };

  // wanted: a doctor id, or '' / 'any' for every doctor who does this treatment
  function eligible(docs, svcId, wanted) {
    const w = clean(wanted).toLowerCase();
    const any = !w || w === 'any';
    return docs.filter(d => doesService(d, svcId) && (any || d.id === w));
  }

  function hoursFor(hoursRows, doctorId, dow) {
    const rows = hoursRows || [];
    const own = rows.filter(r => clean(r[6]).toLowerCase() === doctorId);
    const pool = own.length ? own : rows.filter(r => !clean(r[6]));
    const r = pool.find(x => clean(x[0]).toLowerCase() === dow);
    if (!r || truthy(r[5])) return null;                          // no row or closed = not working
    const open = toMin(r[1] || '10:00'), close = toMin(r[2] || '20:00');
    if (!(close > open)) return null;
    const bs = toMin(r[3]), be = toMin(r[4]);
    return { open, close, brk: bs < be ? [bs, be] : null };
  }

  // Busy blocks for one calendar on one day, in minutes. A calendar Google
  // could not read is treated as fully busy: an unreadable diary must never
  // look empty, or that doctor would be double-booked.
  // Google may answer for "primary" under the account's email address instead.
  // `asked` is every calendar id we asked about: one answer under a key we did
  // not ask for can only be that calendar.
  function busyFor(fb, calId, day, tz, asked) {
    const cal = (fb && fb.calendars) || {};
    let entry = cal[calId];
    if (!entry) {
      const keys = Object.keys(cal);
      const spare = asked ? keys.filter(k => !asked.includes(k)) : keys;
      if (spare.length === 1 && (asked || keys.length === 1)) entry = cal[spare[0]];
    }
    if (!entry || (entry.errors && entry.errors.length)) return { ok: false, blocks: [[0, 1440]] };
    const blocks = [];
    for (const b of entry.busy || []) {
      const s = parts(b.start, tz), e = parts(b.end, tz);
      if (e.date < day || s.date > day) continue;
      blocks.push([s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min]);
    }
    return { ok: true, blocks };
  }

  // Does an appointment of `dur` minutes at `start` fit this doctor's day?
  function fits(start, dur, buffer, h, blocks) {
    if (!h || !(start >= h.open) || start + dur > h.close) return false;
    const all = h.brk ? blocks.concat([h.brk]) : blocks;
    return !all.some(([bs, be]) => start < be && (start + dur + buffer) > bs);
  }

  function freeTimes({ dur, buffer, gran, earliest, h, blocks }) {
    const out = [];
    if (!h) return out;
    for (let t = h.open; t + dur <= h.close; t += gran) {
      if (t < earliest) continue;
      if (fits(t, dur, buffer, h, blocks)) out.push(toHHMM(t));
    }
    return out;
  }

  const busyMinutes = blocks => blocks.reduce((n, [a, b]) => n + Math.max(0, b - a), 0);

  return { clean, toMin, toHHMM, parts, dayName, settings, services, doctors, doesService,
           eligible, hoursFor, busyFor, fits, freeTimes, busyMinutes };
})();
// =============================================================================

const c  = $('Config').first().json;
const vr = $('Read Clinic Config').first().json.valueRanges || [];
const w  = $('Which Doctors').first().json;
const fb = $input.first().json;
const rows = i => (vr[i] && vr[i].values) || [];

const set      = DF.settings(rows(2));
const TZ       = set.timezone || 'Asia/Karachi';
const BUFFER   = Number(set.buffer_min       ?? 10);
const LEAD_H   = Number(set.lead_hours       ?? 2);
const GRAN     = Number(set.slot_granularity ?? 15);
const holidays = new Set(rows(3).map(r => DF.clean(r[0])));

const named = w.eligible.filter(d => !d.implicit).map(d => ({ id: d.id, name: d.name }));
const out = extra => [{ json: { date: c.date, service: c.service, doctor: c.doctor, timezone: TZ,
  slots: [], byDoctor: [], doctors: named, ...extra } }];

const svc = DF.services(rows(0)).find(s => s.id === c.service);
if (!svc)                 return out({ reason: 'unknown-service' });
if (!svc.active)          return out({ reason: 'service-inactive' });

const nowP = DF.parts(new Date().toISOString(), TZ);

/* ---- next=1: the next free times over the coming week --------------------
   For a patient choosing on WhatsApp: instead of "which day?" and then
   "which time?", one short list with real free times. From each day, one in
   the morning, one in the afternoon and one in the evening when there are
   any, earliest days first, at most LIMIT in all. The rules for what counts
   as free are the same DF rules as for a single day, so a time offered here
   is a time the single-day check would also offer.                         */
if (c.next) {
  const LIMIT = 8;
  const asked = w.eligible.map(x => x.calendarId);
  const addDays = (ymd, n) => new Date(Date.parse(ymd + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
  const part = t => { const m = DF.toMin(t); return m < 720 ? 0 : m < 1020 ? 1 : 2; };     // before 12:00, before 17:00, later
  const WD = { en: 'en-GB', ar: 'ar-EG-u-nu-latn-ca-gregory', ur: 'ur-PK-u-nu-latn-ca-gregory' }[c.lang] || 'en-GB';
  const noon = ymd => new Date(ymd + 'T12:00:00Z');
  const clock = t => { const [h, m] = t.split(':').map(Number);
    return `${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${c.lang === 'ar' ? (h >= 12 ? 'م' : 'ص') : (h >= 12 ? 'PM' : 'AM')}`; };
  // A row title on WhatsApp holds 24 characters. English: "Fri 9 Oct · 3:00 PM". Arabic and Urdu day names are
  // longer, so the date is written day/month: "الجمعة 9/10 · 3:00 م".
  const label = (ymd, t) => {
    const [, mo, d] = ymd.split('-').map(Number);
    const day = c.lang === 'en'
      ? `${noon(ymd).toLocaleDateString(WD, { timeZone: 'UTC', weekday: 'short' })} ${d} ${noon(ymd).toLocaleDateString(WD, { timeZone: 'UTC', month: 'short' })}`
      : `${noon(ymd).toLocaleDateString(WD, { timeZone: 'UTC', weekday: 'long' })} ${d}/${mo}`;
    return `${day} · ${clock(t)}`;
  };

  const options = [], unreadable = new Set();
  let worked = 0;
  for (let i = 0; i <= c.NEXT_DAYS && options.length < LIMIT; i++) {
    const date = addDays(nowP.date, i);
    if (holidays.has(date)) continue;
    const dow = DF.dayName(date, TZ);
    const earliest = i === 0 ? nowP.min + LEAD_H * 60 : -1;
    const free = new Map();                                  // time -> the dentists free then
    for (const d of w.eligible) {
      const h = DF.hoursFor(rows(1), d.id, dow);
      if (!h) continue;
      worked++;
      const busy = DF.busyFor(fb, d.calendarId, date, TZ, asked);
      if (!busy.ok) { unreadable.add(d.id); continue; }      // never guess at a diary we can't read
      const load = DF.busyMinutes(busy.blocks);
      for (const t of DF.freeTimes({ dur: svc.min, buffer: BUFFER, gran: GRAN, earliest, h, blocks: busy.blocks })) {
        if (!free.has(t)) free.set(t, []);
        free.get(t).push({ d, load });
      }
    }
    const times = [...free.keys()].sort();
    const picked = [0, 1, 2].map(p => times.find(t => part(t) === p)).filter(Boolean);
    for (const t of picked) {
      if (options.length >= LIMIT) break;
      const who = free.get(t).sort((a, b) => a.load - b.load)[0].d;      // the dentist with the lighter day
      options.push({ label: label(date, t), date, time: t,
                     doctor: who.implicit ? '' : who.id, doctorName: who.implicit ? '' : who.name });
    }
  }
  return [{ json: { next: true, service: c.service, serviceName: svc.name, durationMin: svc.min, price: svc.price,
    doctor: c.doctor, timezone: TZ, doctors: named, options,
    ...(options.length ? {} : { reason: worked ? 'nothing-free-this-week' : 'closed' }),
    ...(unreadable.size ? { unreadable: [...unreadable] } : {}),
    how: 'Offer these in this order, each label exactly as written, with doctorName as the small second line when it is not empty. ' +
         'To book one, pass its date, time and doctor to create_booking (doctor "any" when it is empty).' } }];
}

if (holidays.has(c.date)) return out({ reason: 'holiday' });

const dow  = DF.dayName(c.date, TZ);
const earliest = nowP.date === c.date ? nowP.min + LEAD_H * 60 : (c.date < nowP.date ? 99999 : -1);

const byDoctor = [], unreadable = [];
let working = 0;
for (const d of w.eligible) {
  const h = DF.hoursFor(rows(1), d.id, dow);
  if (!h) continue;                                       // not working that day
  working++;
  const busy = DF.busyFor(fb, d.calendarId, c.date, TZ, w.eligible.map(x => x.calendarId));
  if (!busy.ok) { unreadable.push(d.id); continue; }      // never guess at a diary we can't read
  const slots = DF.freeTimes({ dur: svc.min, buffer: BUFFER, gran: GRAN, earliest, h, blocks: busy.blocks });
  if (slots.length) byDoctor.push({ doctor: d.implicit ? '' : d.id, doctorName: d.implicit ? '' : d.name, slots });
}
// "slots" stays a plain list of times (every free time, across the chosen
// doctors) so older booking pages keep working; byDoctor says who is free when.
const slots = [...new Set(byDoctor.flatMap(b => b.slots))].sort();
const reason = slots.length ? undefined : (working ? 'fully-booked' : 'closed');
return out({ serviceName: svc.name, durationMin: svc.min, price: svc.price, slots, byDoctor,
  ...(reason ? { reason } : {}), ...(unreadable.length ? { unreadable } : {}) });

